// ProductList.vue
<template>
  <div class="container mt-4">
    <h3>📦 Product Inventory</h3>

    <div v-if="paginated.length === 0">No products found.</div>
    <div v-for="product in paginated" :key="product.id" class="card mb-3">
      <div class="card-body">
        <h5>{{ product.name }}</h5>
        <p>{{ product.description }}</p>
        <p>₱{{ product.price }} — Stock: {{ product.stock }}</p>
        <img
          v-if="product.image"
          :src="fullImageUrl(product.image)"
          alt="Product image"
          class="img-thumbnail mb-2"
          style="max-height: 120px;"
        />

        <button class="btn btn-sm btn-primary me-2" @click="openEditModal(product)">Edit</button>
        <button class="btn btn-sm btn-danger" @click="deleteProduct(product.id)">Delete</button>
      </div>
    </div>

    <!-- Pagination -->
    <nav v-if="totalPages > 1">
      <ul class="pagination justify-content-center mt-3">
        <li class="page-item" :class="{ disabled: currentPage === 1 }">
          <a class="page-link" href="#" @click.prevent="currentPage--">Previous</a>
        </li>
        <li
          v-for="n in totalPages"
          :key="n"
          class="page-item"
          :class="{ active: currentPage === n }"
        >
          <a class="page-link" href="#" @click.prevent="currentPage = n">{{ n }}</a>
        </li>
        <li class="page-item" :class="{ disabled: currentPage === totalPages }">
          <a class="page-link" href="#" @click.prevent="currentPage++">Next</a>
        </li>
      </ul>
    </nav>

    <!-- Edit Modal -->
    <div class="modal fade" ref="editModal" id="editModal">
      <div class="modal-dialog">
        <div class="modal-content">
          <form @submit.prevent="submitEdit">
            <div class="modal-header">
              <h5 class="modal-title">Edit Product</h5>
              <button type="button" class="btn-close" @click="closeEditModal"></button>
            </div>
            <div class="modal-body">
              <input v-model="editProduct.name" class="form-control mb-2" placeholder="Name" required />
              <input v-model="editProduct.description" class="form-control mb-2" placeholder="Description" required />
              <input type="number" v-model.number="editProduct.price" class="form-control mb-2" placeholder="Price" required />
              <input type="number" v-model.number="editProduct.stock" class="form-control mb-2" placeholder="Stock" required />
              <input type="file" @change="handleEditImage" class="form-control mb-2" accept="image/*" />
            </div>
            <div class="modal-footer">
              <button type="button" class="btn btn-secondary" @click="closeEditModal">Cancel</button>
              <button type="submit" class="btn btn-success">Save</button>
            </div>
          </form>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import axios from '../axios'
import * as bootstrap from 'bootstrap'

export default {
  data() {
    return {
      products: [],
      currentPage: 1,
      perPage: 5,
      editProduct: { id: null, name: '', description: '', price: 0, stock: 0 },
      editImage: null,
      modalInstance: null
    }
  },
  computed: {
    totalPages() {
      return Math.ceil(this.products.length / this.perPage)
    },
    paginated() {
      const start = (this.currentPage - 1) * this.perPage
      return this.products.slice(start, start + this.perPage)
    }
  },
  methods: {
    fullImageUrl(path) {
      if (path.startsWith('http')) return path
      return `http://127.0.0.1:8000${path.startsWith('/') ? path : '/media/' + path}`
    },
    async fetchProducts() {
      try {
        const res = await axios.get('products/')
        this.products = res.data
      } catch {
        alert('❌ Failed to load products.')
      }
    },
    async deleteProduct(id) {
      try {
        await axios.delete(`products/${id}/`)
        alert('🗑️ Product deleted.')
        this.fetchProducts()
      } catch {
        alert('❌ Cannot delete product.')
      }
    },
    openEditModal(product) {
      this.editProduct = { ...product }
      this.editImage = null
      this.modalInstance = new bootstrap.Modal(this.$refs.editModal)
      this.modalInstance.show()
    },
    closeEditModal() {
      if (this.modalInstance) this.modalInstance.hide()
    },
    handleEditImage(e) {
      this.editImage = e.target.files[0]
    },
    async submitEdit() {
      const formData = new FormData()
      for (let key in this.editProduct) {
        if (key !== 'image') {
          formData.append(key, this.editProduct[key])
        }
      }
      if (this.editImage) {
        formData.append('image', this.editImage)
      }

      try {
        await axios.patch(`products/${this.editProduct.id}/`, formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        })
        alert('✅ Product updated!')
        this.fetchProducts()
        this.closeEditModal()
      } catch (err) {
        alert('❌ Failed to update product.')
      }
    }
  },
  mounted() {
    const token = localStorage.getItem('access')
    const isStaff = localStorage.getItem('is_staff') === 'true'
    if (!token || !isStaff) {
      alert('⛔ Access denied. Staff only.')
      this.$router.push('/login')
      return
    }
    this.fetchProducts()
  }
}
</script>

<style>
/* Brown and neutral color palette */
:root {
  --brown-primary: #8B6E4E;
  --brown-dark: #6D563D;
  --brown-light: #A48C71;
  --brown-lighter: #C7B299;
  --brown-lightest: #E0D3BD;
  --neutral-100: #F8F6F2;
  --neutral-200: #EBE6DD;
  --neutral-300: #D9D2C5;
  --neutral-400: #A99F8F;
  --neutral-500: #7C7368;
}

/* Global styles for elegant look */
body {
  background-color: var(--neutral-100);
  color: #332e28;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

.container {
  background-color: white;
  padding: 25px;
  border-radius: 10px;
  box-shadow: 0 3px 15px rgba(0, 0, 0, 0.05);
}

/* Header styling */
h3 {
  color: var(--brown-primary);
  font-weight: 400;
  border-bottom: 2px solid var(--neutral-200);
  padding-bottom: 12px;
  margin-bottom: 25px;
}

/* Card styling */
.card {
  border: none;
  box-shadow: 0 2px 10px rgba(139, 110, 78, 0.07);
  transition: all 0.2s ease;
  border-left: 3px solid var(--brown-primary);
  background-color: var(--neutral-100);
}

.card:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(139, 110, 78, 0.15);
}

.card-body {
  padding: 20px;
}

.card h5 {
  color: var(--brown-dark);
  font-weight: 500;
  margin-bottom: 10px;
}

.card p {
  color: var(--neutral-500);
}

/* Image styling */
.img-thumbnail {
  border-color: var(--neutral-300);
  padding: 0.25rem;
}

/* Button styling */
.btn-primary {
  background-color: var(--brown-primary);
  border-color: var(--brown-primary);
}

.btn-primary:hover {
  background-color: var(--brown-dark);
  border-color: var(--brown-dark);
}

.btn-danger {
  background-color: #a16955;
  border-color: #a16955;
}

.btn-danger:hover {
  background-color: #8c5a49;
  border-color: #8c5a49;
}

.btn-success {
  background-color: #7e9169;
  border-color: #7e9169;
}

.btn-success:hover {
  background-color: #6a7b58;
  border-color: #6a7b58;
}

.btn-secondary {
  background-color: var(--neutral-400);
  border-color: var(--neutral-400);
}

/* Pagination styling */
.pagination .page-link {
  color: var(--brown-primary);
  background-color: white;
  border-color: var(--neutral-300);
}

.pagination .page-item.active .page-link {
  background-color: var(--brown-primary);
  border-color: var(--brown-primary);
}

.pagination .page-item.disabled .page-link {
  color: var(--neutral-400);
}

/* Modal styling */
.modal-content {
  border: none;
  box-shadow: 0 5px 25px rgba(0, 0, 0, 0.1);
}

.modal-header {
  background-color: var(--brown-primary);
  color: white;
  border-bottom: none;
}

.modal-footer {
  background-color: var(--neutral-100);
  border-top: none;
}

.form-control {
  border-color: var(--neutral-300);
  background-color: white;
}

.form-control:focus {
  border-color: var(--brown-light);
  box-shadow: 0 0 0 0.25rem rgba(139, 110, 78, 0.25);
}

/* Add soft transitions for interactive elements */
.btn, .form-control, .page-link {
  transition: all 0.2s ease-in-out;
}
</style>
